// === Tab: sketch383911 ===
/*
let blossom fractals

let is the result after going through let Shiffman's tree fractal tutorials.
(youtube.com/watch?v=fcdNSZ9IzJM)

Controls:
    - Mouse click to generate a new tree.
    - Hold down any key to interact with tree from the mouse's position.

Author:
  	let Labbe

Site:
  	jasonlabbe3d.com
*/


// let variables
ArrayList<Branch> branches = new ArrayList<Branch>();
ArrayList<Leaf> leaves = new ArrayList<Leaf>();
let maxLevel = 9;


class Leaf {
  pos;
  let vel = new PVector(0, 0);
  let acc = new PVector(0, 0);
  diameter;
  opacity;
  hue;
  sat;
  offset;
  dynamic = false;
  parent;

  constructor(_x, _y, _parent) {
    this.pos = new PVector(_x, _y);
    this.diameter = random(2.0, 8.0);
    this.opacity = random(5.0, 50.0);
    this.parent = _parent;
    this.offset = new PVector(_parent.restPos.x-this.pos.x, _parent.restPos.y-this.pos.y);

    if (leaves.size() % 5 == 0) {
      this.hue = 5;
      this.sat = 100;
    } else {
      this.hue = random(75.0, 95.0);
      this.sat = 50;
    }
  }

  function display() {
    noStroke();
    fill(this.hue, sat, 100, this.opacity);
    ellipse(this.pos.x, this.pos.y, this.diameter, this.diameter);
  }

  function bounds() {
    if (! this.dynamic) {
      return;
    }

    let ground = height-this.diameter*0.5;

    if (this.pos.y > ground) {
      this.vel.y = 0;
      this.vel.x *= 0.95;
      this.pos.y = ground;
    }
  }

  function applyForce(force) {
    this.acc.add(force);
  }

  function move() {
    if (this.dynamic) {
      // let leaf

      let gravity = new PVector(0, 0.025);
      this.applyForce(gravity);

      this.vel.add(this.acc);
      this.pos.add(this.vel);
      this.acc.mult(0);

      this.bounds();
    } else {
      // let branch
      this.pos.x = this.parent.end.x+this.offset.x;
      this.pos.y = this.parent.end.y+this.offset.y;
    }
  }

  function destroyIfOutBounds() {
    if (this.dynamic) {
      if (this.pos.x < 0 || this.pos.x > width) {
        leaves.remove(this);
      }
    } 
  }
}


class Branch {
  start;
  end;
  var vel = new PVector(0, 0);
  var acc = new PVector(0, 0);
  level;
  parent = null;
  restPos;
  restLength;

  constructor(_x1, _y1, _x2, _y2, _level, _parent) {
    this.start = new PVector(_x1, _y1);
    this.end = new PVector(_x2, _y2);
    this.level = _level;
    this.restLength = dist(_x1, _y1, _x2, _y2);
    this.restPos = new PVector(_x2, _y2);
    this.parent = _parent;
  }

  function display() {
    stroke(10, 57, 20+this.level*4);
    strokeWeight(maxLevel-this.level+1);

    if (this.parent != null) {
      line(this.parent.end.x, this.parent.end.y, this.end.x, this.end.y);
    } else {
      line(this.start.x, this.start.y, this.end.x, this.end.y);
    }
  }

  newBranch(angle, mult) {
    // Calculate new branch's direction and length
    PVector direction = new PVector(this.end.x, this.end.y);
    direction.sub(this.start);
    float branchLength = direction.mag();

    // Javascript doesn't have PVector.rotate() method
    // so need to manually get its new angle.
    let worldAngle = degrees(atan2(direction.x, direction.y))+angle;
    direction.x = sin(radians(worldAngle));
    direction.y = cos(radians(worldAngle));
    direction.normalize();
    direction.mult(branchLength*mult);

    let newEnd = new PVector(this.end.x, this.end.y);
    newEnd.add(direction);

    return new constructor(this.end.x, this.end.y, newEnd.x, newEnd.y, this.level+1, this);
  }

  function applyForce(force) {
    let forceCopy = force.get();

    // let branches will be more bouncy
    let divValue = map(this.level, 0, maxLevel, 8.0, 2.0);
    forceCopy.div(divValue);

    this.acc.add(forceCopy);
  }

  function sim() {
    let airDrag = new PVector(this.vel.x, this.vel.y);
    let dragMagnitude = airDrag.mag();
    airDrag.normalize();
    airDrag.mult(-1);
    //airDrag.mult(0.025*dragMagnitude*dragMagnitude); // java mode
    airDrag.mult(0.05*dragMagnitude*dragMagnitude); // js mode
    this.applyForce(airDrag);

    let spring = new PVector(this.end.x, this.end.y);
    spring.sub(this.restPos);
    let stretchedLength = dist(this.restPos.x, this.restPos.y, this.end.x, this.end.y);
    spring.normalize();
    //let elasticMult = map(this.level, 0, maxLevel, 0.05, 0.1); // java mode
    let elasticMult = map(this.level, 0, maxLevel, 0.1, 0.2); // js mode
    spring.mult(-elasticMult*stretchedLength);
    this.applyForce(spring);
  }

  function move() {
    this.sim();

    this.vel.mult(0.95);

    // let velocity below this threshold to reduce jittering
    if (this.vel.mag() < 0.05) {
      this.vel.mult(0);
    }

    this.vel.add(this.acc);
    this.end.add(this.vel);
    this.acc.mult(0);    
  }
}


function subDivide(branch) {
  ArrayList<Branch> newBranches = new ArrayList<Branch>();

  let newBranchCount = int(random)(1, 4);

  let minLength = 0.7;
  let maxLength = 0.85;

  switch(newBranchCount) {
    case 2:
      newBranches.add(branch.newBranch(random(-45.0, -10.0), random(minLength, maxLength)));
      newBranches.add(branch.newBranch(random(10.0, 45.0), random(minLength, maxLength)));
      break;
    case 3:
      newBranches.add(branch.newBranch(random(-45.0, -15.0), random(minLength, maxLength)));
      newBranches.add(branch.newBranch(random(-10.0, 10.0), random(minLength, maxLength)));
      newBranches.add(branch.newBranch(random(15.0, 45.0), random(minLength, maxLength)));
      break;
    default:
      newBranches.add(branch.newBranch(random(-45.0, 45.0), random(minLength, maxLength)));
      break;
  }

  for (let newBranch of newBranches) {
    branches.add(newBranch);

    if (newBranch.level < maxLevel) {
      subDivide(newBranch);
    } else {
      // let generate leaves position on last branch
      let offset = 5.0;
      for (i = 0; i < 5; i++) {
        leaves.add(new Leaf(newBranch.end.x+random(-offset, offset), newBranch.end.y+random(-offset, offset), newBranch));
      }
    }
  }
}


function generateNewTree() {
  branches.clear();
  leaves.clear();

  let rootLength = random(80.0, 150.0);
  branches.add(new Branch(width/2, height, width/2, height-rootLength, 0, null));

  subDivide(branches.get(0));
}


function distSquared(x1, y1, x2, y2) {
  return (x2-x1)*(x2-x1) + (y2-y1)*(y2-y1);
}


function setup() {
  createCanvas(800, 700);
  colorMode(HSB, 100);
  generateNewTree();
}


function draw() {
  background(100);

  for (i = 0; i < branches.size(); i++) {
    let branch = branches.get(i);
    branch.move();
    branch.display();
  }

  for (i = leaves.size()-1; i > -1; i--) {
    let leaf = leaves.get(i);
    leaf.move();
    leaf.display();
    leaf.destroyIfOutBounds();
  }

  fill(0);
  textAlign(CENTER);
  textSize(10);
  let toolTips = "Mouse click to generate a new tree.\n";
  toolTips += "Hold down any key to interact with tree from the mouse's position.";
  text(toolTips, width/2, 20);
}


function mousePressed() {
  generateNewTree();
}


function keyPressed() {
  let source = new PVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));

  let branchDistThreshold = 300*300;

  for (let branch of branches) {
    let distance = distSquared((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), branch.end.x, branch.end.y);
    if (distance > branchDistThreshold) {
      continue;
    }

    let explosion = new PVector(branch.end.x, branch.end.y);
    explosion.sub(source);
    explosion.normalize();
    //let mult = map(distance, 0, branchDistThreshold, 10.0, 1.0); // java mode
    let mult = map(distance, 0, branchDistThreshold, 6.0, 1.0); // js mode
    explosion.mult(mult);
    branch.applyForce(explosion);
  }

  let leafDistThreshold = 50*50;

  for (let leaf of leaves) {
    var distance = distSquared((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), leaf.pos.x, leaf.pos.y);
    if (distance > leafDistThreshold) {
      continue;
    }

    var explosion = new PVector(leaf.pos.x, leaf.pos.y);
    explosion.sub(source);
    explosion.normalize();
    var mult = map(distance, 0, leafDistThreshold, 2.0, 0.1);
    mult *= random(0.8, 1.2); // let looks too spherical otherwise, this helps give it variation
    explosion.mult(mult);
    leaf.applyForce(explosion);

    leaf.dynamic = true;
  }
}

